#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using mint = ModInt<1000000007>;
template<unsigned int mod_>
struct ModInt{
	using ull = unsigned long long;
	constexpr static unsigned int mod = mod_;
	unsigned int v;
	ModInt():v(0){}
	ModInt(ll _v):v(normS(_v%mod+mod)){}
	static unsigned int normS(const unsigned int &x){return (x<mod)?x:x-mod;}
	static ModInt make(const unsigned int &x){ModInt m; m.v=x; return m;}
	ModInt operator+(const ModInt& b) const { return make(normS(v+b.v));}
	ModInt operator-(const ModInt& b) const { return make(normS(v+mod-b.v));}
	ModInt operator-() const { return make(normS(mod-v)); }
	ModInt operator*(const ModInt& b) const { return make((ull)v*b.v%mod);}
	ModInt operator/(const ModInt& b) const { return *this*b.inv();}
	ModInt& operator+=(const ModInt& b){ return *this=*this+b;}
	ModInt& operator-=(const ModInt& b){ return *this=*this-b;}
	ModInt& operator*=(const ModInt& b){ return *this=*this*b;}
	ModInt& operator/=(const ModInt& b){ return *this=*this/b;}
	ModInt inv() const {
		ll x,y;
		extgcd(v,mod,x,y);
		return make(normS(x+mod));
	}
	ModInt pow(ll p) const {
		if(p<0) return inv().pow(-p);
		ModInt a=1, x=*this;
		while(p){ if(p&1) a*=x; x*=x; p>>=1; }
		return a;
	}
	ll extgcd(ll a,ll b,ll &x,ll &y) const{
		ll p[]={a,1,0},q[]={b,0,1};
		while(*q){
			ll t=*p/ *q;
			for(int i=0;i<3;i++) swap(p[i]-=t*q[i],q[i]);
		}
		if(p[0]<0) for(int i=0;i<3;i++) p[i]=-p[i];
		x=p[1]; y=p[2];
		return p[0];
	}
	bool operator==(const ModInt& b) const { return v==b.v;}
	bool operator!=(const ModInt& b) const { return v!=b.v;}
	friend istream& operator>>(istream &o,ModInt& x){ ll tmp; o>>tmp; x=ModInt(tmp); return o;}
	friend ostream& operator<<(ostream &o,const ModInt& x){ return o<<x.v;}
};

using BS = bitset<128>;
bool B(int x,int i){return (x>>i)&1;}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(20);
	int n;
	cin >> n;
	vector<vector<mint>> p(n, vector<mint>(n));
	for(int i=0;i<n;i++) for(int j=0;j<n;j++){ cin>>p[i][j]; p[i][j] /= 100; }

	map<BS,mint> cur, nxt;
	{
		BS b; b[0]=true; cur[b]=mint(1);
	}
	for(int i=0;i<n;i++){
		for(auto &it : cur){
			BS b = it.first;
			vector<int> ones;
			for(int x=0; x < (1<<n); ++x) if(b[x]) ones.push_back(x);
			for(int e=0; e < (1<<n); ++e){
				mint prob = 1;
				for(int j=0;j<n;j++){
					if(B(e,j)) prob *= p[i][j];
					else prob *= mint(1) - p[i][j];
				}
				BS nb;
				for(int x : ones){
					for(int r=0; r<n; ++r){
						if(B(e,r) && !B(x,r)) nb[x | (1<<r)] = true;
					}
				}
				nxt[nb] += it.second * prob;
			}
		}
		cur = nxt;
		nxt.clear();
	}
	mint ans = 0;
	for(auto &it : cur) if(it.first[(1<<n)-1]) ans += it.second;
	cout << ans << '\n';
}
